def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    fill = 3

    # the marker colour: the single non-background colour present (8 in all pairs)
    cols = [c for c in np.unique(g) if c != bg]
    marker = cols[0] if cols else None
    if marker is None:
        emit(out, "No markers; nothing to connect.")
        return out

    pts = [(int(y), int(x)) for y, x in zip(*np.where(g == marker))]

    # group by row, join consecutive markers horizontally
    by_row = {}
    for y, x in pts:
        by_row.setdefault(y, []).append(x)
    for y in sorted(by_row):
        xs = sorted(by_row[y])
        for a, b in zip(xs, xs[1:]):
            if b - a > 1:
                for x in range(a + 1, b):
                    if out[y, x] == bg:
                        out[y, x] = fill
                emit(out, f"Row {y}: markers at x={a} and x={b} are aligned; fill the gap between them with colour {fill}.")

    # group by column, join consecutive markers vertically
    by_col = {}
    for y, x in pts:
        by_col.setdefault(x, []).append(y)
    for x in sorted(by_col):
        ys = sorted(by_col[x])
        for a, b in zip(ys, ys[1:]):
            if b - a > 1:
                for y in range(a + 1, b):
                    if out[y, x] == bg:
                        out[y, x] = fill
                emit(out, f"Column {x}: markers at y={a} and y={b} are aligned; fill the gap between them with colour {fill}.")

    emit(out, "All aligned marker pairs bridged; unpaired markers stay as they are.")
    return out
